import { useEffect, useState } from "react";
import axios from "axios";

export default function TeacherDashboard() {
  const [courses, setCourses] = useState([]);
  const [submissions, setSubmissions] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const courseRes = await axios.get("/api/teachers/1/courses");
      const subRes = await axios.get("/api/teachers/1/submissions");

      setCourses(courseRes.data);
      setSubmissions(subRes.data);
    } catch (err) {
      console.log(err);
    }
  };

  return (
    <div className="p-6">
      {/* HEADER */}
      <h1 className="text-2xl font-bold mb-2">
        Dr. Riya Sharma
      </h1>
      <p className="text-gray-500 mb-6">
        Teacher Dashboard
      </p>

      {/* STATS */}
      <div className="flex gap-10 mb-6">
        <div>
          <p className="text-gray-500 text-sm">My courses</p>
          <h2 className="text-2xl font-semibold">
            {courses.length}
          </h2>
        </div>

        <div>
          <p className="text-gray-500 text-sm">Total students</p>
          <h2 className="text-2xl font-semibold">
            {courses.reduce(
              (sum, c) => sum + (c.student_count || 0),
              0
            )}
          </h2>
        </div>

        <div>
          <p className="text-gray-500 text-sm">Submissions</p>
          <h2 className="text-2xl font-semibold">
            {submissions.length}
          </h2>
        </div>
      </div>

      {/* COURSES */}
      <div className="mb-6">
        <h2 className="text-lg font-semibold mb-3">
          My Courses
        </h2>

        {courses.map((c) => (
          <div
            key={c.course_id}
            className="border p-4 rounded mb-3"
          >
            <h3 className="font-medium">
              {c.course_name}
            </h3>
            <p className="text-sm text-gray-500">
              {c.student_count} students
            </p>
          </div>
        ))}
      </div>

      {/* SUBMISSIONS */}
      <div>
        <h2 className="text-lg font-semibold mb-3">
          Recent Submissions
        </h2>

        {submissions.length === 0 ? (
          <p className="text-gray-500">
            No submissions yet
          </p>
        ) : (
          submissions.slice(0, 5).map((s) => (
            <div
              key={s.submission_id}
              className="border p-4 rounded mb-3"
            >
              <p className="font-medium">
                {s.student_name}
              </p>
              <p className="text-sm text-gray-500">
                {s.assignment_title}
              </p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
